app.post('/api/payment/vnpay-ipn', async (req, res) => {
  const isValidSignature = verifyChecksum(req.body);
  if (!isValidSignature) return res.status(400).json({ RspCode: '97', Message: 'Invalid Checksum' });

  const order = await db.orders.findById(req.body.orderId);
  if (order.status === 'PAID') return res.json({ RspCode: '02', Message: 'Order already confirmed' }); // Idempotent

  await db.orders.updateStatus(order.id, 'PAID');
  return res.json({ RspCode: '00', Message: 'Success' });
});

