const chars = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
function toBase62(num: bigint): string {
  let str = '';
  while (num > 0n) { str = chars[Number(num % 62n)] + str; num /= 62n; }
  return str;
}

